$summary='Operations specialist with experience coordinating projects and documenting procedures. Brings clear reporting and a practical approach to team communication.';
$good=$service(['section'=>'summary','summary'=>$summary],static function($payload)use($check){$check($payload['store']===false,'AI requests must not be stored.');$check($payload['text']['format']['strict']===true,'Section output must use a strict schema.');$check(!str_contains($payload['instructions'],'Requires Kubernetes'),'Job-ad data must not enter trusted instructions.');$check(str_contains($payload['instructions'],'profileType'),'Summary instructions must honour the selected profile type.');$check(str_contains($payload['instructions'],ResumePrompts::VERSION),'Prompts must be versioned.');});
$check($good->suggestSection('summary',['summary'=>''],$context)['summary']===$summary,'A grounded natural summary should pass.');
$throws(fn()=>$service(['section'=>'summary','summary'=>'Manager with 15 years of experience who delivers technical projects.'])->suggestSection('summary',['summary'=>''],$context),'Job-ad numbers must not substantiate applicant experience.');
$emptySkills=['technical'=>[],'software'=>[],'interpersonal'=>[],'language'=>[],'custom'=>[]];
$adSkill=$emptySkills;$adSkill['technical']=[['name'=>'Kubernetes','evidence'=>'Requires Kubernetes, German fluency and 15 years of management.']];
$throws(fn()=>$service(['section'=>'skills','skills'=>$adSkill])->suggestSection('skills',[],$context),'A job-ad quote must not support a skill.');
$realSkill=$emptySkills;$realSkill['software']=[['name'=>'Microsoft Excel','evidence'=>'Microsoft Excel, Power BI, Asana']];
$check(str_contains($service(['section'=>'skills','skills'=>$realSkill])->suggestSection('skills',[],$context)['skills']['software'],'Microsoft Excel'),'An exact applicant skill quote should pass.');
