$throws(fn()=>$service(['section'=>'certifications','items'=>[['index'=>0,'text'=>'Data Certificate - Academy, 2027']]])->suggestSection('certifications',$cert,$context),'A draft must retain in-progress status.');
$check(count($service(['section'=>'certifications','items'=>$cert['items']])->suggestSection('certifications',$cert,$context)['items'])===1,'An unchanged honest credential status should pass.');
$two=['items'=>[['index'=>0,'text'=>'Service award, 2024'],['index'=>1,'text'=>'Team award, 2023']]];
$throws(fn()=>$service(['section'=>'achievements','items'=>[['index'=>0,'text'=>'Service award, 2024'],['index'=>1,'text'=>'Team award, 2025']]])->suggestSection('achievements',$two,$context),'A bad item must not silently disappear from a partial suggestion.');
$application=['company'=>'Example Studio','role'=>'Operations Specialist','job_description'=>'Requires 15 years of experience.','company_details'=>''];
$letter="I am applying for the Operations Specialist role at Example Studio. My project coordination experience would support clear reporting and organised delivery.\n\nI coordinated team updates and documented operating procedures. I would bring that practical approach to your team and would welcome the opportunity to discuss the role.";
$check($service($letter)->suggestCoverLetter($context,$application)===$letter,'Natural first-person letters should pass without resume-style pronoun restrictions.');
$throws(fn()=>$service(str_replace('My project coordination experience','My 15 years of project coordination experience',$letter))->suggestCoverLetter($context,$application),'Cover letter numbers cannot be borrowed from the job ad.');
$throws(fn()=>$service(str_replace('I coordinated team updates','I doubled team productivity',$letter))->suggestCoverLetter($context,$application),'Spelled-out unsupported quantitative claims must be rejected.');
$past=['entries'=>[['index'=>0,'role'=>'Coordinator','company'=>'Example Studio','bullets'=>[['index'=>0,'text'=>'Prepared project reports for weekly team meetings.']]]]];
$throws(fn()=>$service(['section'=>'experience','entries'=>[['index'=>0,'description'=>'','bullets'=>[['index'=>0,'text'=>'Prepared reports and reduced costs by 35%.']]]]])->suggestSection('experience',$past,$context),'Experience bullets must reject unsupported metrics.');
$supported=$past;$supported['entries'][0]['bullets'][0]['text']='Assisted the team with preparing weekly project reports.';
$throws(fn()=>$service(['section'=>'experience','entries'=>[['index'=>0,'description'=>'','bullets'=>[['index'=>0,'text'=>'Led the team in preparing weekly project reports.']]]]])->suggestSection('experience',$supported,$context),'A supporting contribution must not become leadership.');

$review=$ats->analyze($base);$without=$base;$without['summary']='';
$check(!in_array('Professional summary',array_column($ats->analyze($without)['checks'],'label'),true),'A missing optional summary must not be required.');
$volunteer=$without;$volunteer['experience']=[];$volunteer['projects']=[];$volunteer['extracurricular']=[['organization'=>'Community Centre','role'=>'Volunteer','bullets'=>['Coordinated weekly learning sessions and prepared materials for the volunteer team.']]];
$v=$ats->analyze($volunteer);$e=array_values(array_filter($v['checks'],static fn($c)=>$c['label']==='Relevant evidence'))[0];
$check($e['status']==='pass','Volunteering must count as legitimate experience evidence.');
$numbers=$without;$numbers['experience']=[];$numbers['projects']=[];$numbers['certifications']=['Certificate, 2024','Course, 2025'];
$check($ats->analyze($numbers)['score']<=54,'Certification years must not manufacture contribution evidence.');
$bad=$base;$bad['personal']['email']='not-an-email';$check($ats->analyze($bad)['score']<=69,'Invalid contact formats must not receive a strong readiness result.');
$bad=$base;$bad['experience'][0]['startDate']='2025-13';$check(in_array('improve',array_column(array_filter($ats->analyze($bad)['checks'],static fn($c)=>$c['label']==='Consistent dates'),'status'),true),'Invalid dates must be flagged.');
$short=$base;$short['writing']=['profileType'=>'objective'];$short['summary']='Business graduate seeking an operations role, bringing project reporting experience and a practical approach to documentation and teamwork.';
$check(array_values(array_filter($ats->analyze($short)['checks'],static fn($c)=>$c['label']==='Focused objective'))[0]['status']==='pass','A useful short objective must not be padded to an arbitrary minimum.');
$ordered=ResumeWriting::orderedEntries([['id'=>'old','endDate'=>'2021-06'],['id'=>'unknown'],['id'=>'current','endDate'=>'Present'],['id'=>'new','endDate'=>'2025-03']],'newest');
$check(array_column($ordered,'id')===['current','unknown','new','old'],'Date sorting must be stable and preserve unknown-date positions.');
$extra=Sanitizer::sanitizeResume(['additional'=>[['kind'=>['bad'],'title'=>'<script>heading</script>','items'=>['A supplied entry']]]]);
$check(count($extra['additional'])===1,'Malformed kinds should be safely normalised.');
$html=ResumeTemplate::buildHtml($extra);$check(!str_contains($html,'<script>'),'Additional section titles must be escaped.');
$cv=$base;$cv['writing']=['documentType'=>'academic-cv','profileType'=>'objective'];$cv['additional']=[['kind'=>'publications','items'=>['Tan, A. (2025). Sample study. Submitted manuscript.']]];
$html=ResumeTemplate::buildHtml($cv);$check(str_contains($html,'Objective')&&str_contains($html,'Publications')&&str_contains($html,'Submitted manuscript'),'The export must include the selected profile label and supplied CV sections.');
$check(ResumeWriting::filename($cv)==='Zamir_Zaini_CV.pdf','CV downloads need a meaningful filename.');
$check(ResumeWriting::filename($cv,'letter')==='Zamir_Zaini_Cover_Letter.pdf','Letters need a matching professional filename.');
$check(!str_contains(ResumeWriting::filename(['personal'=>['fullName'=>"Bad\r\nHeader\"/Name"]]),"\n"),'Filenames must not introduce header control characters.');
foreach(['10','10.5','11','11.5','12'] as $size)$check(Sanitizer::appearance(['size'=>$size])['size']===$size,'Supported readable body sizes must persist.');
$check(Sanitizer::appearance(['size'=>'8'])['size']==='11','Unreadably small or invalid sizes must fall back to the default.');
echo "Writing review, CV structure, privacy, prompt payloads and mocked AI response checks passed ($count assertions; no API or database calls).\n";
